impl std::fmt::Display for ArgOwner {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Shared => f.write_str("SharedArgs"),
            Self::Line(name) => write!(f, "model line {name}"),

